[2199] = { en = "Lore for a Price", tier = 3,
  t = "Kennis heeft een prijs",
  d = "Ik ben een zeer beroemde juwelier hier in Ironforge! Nou ja, vroeger was ik beroemd... Door de oneerlijke trucs van een concurrent heb ik het nu moeilijk. In dit vak betekent een slechte naam een financiële ramp. Daardoor heb ik geen koperstuk meer op mijn naam. Die naam is goed, maar op dit moment wel bevlekt.$B$BIk wil dat je vijf zilverstaven voor me haalt. Daarmee kan ik een bestelling afmaken die ik heb gekregen: de eerste in wat een eeuwigheid lijkt.$B$BAls je me die vijf zilverstaven brengt, beantwoord ik je vragen over de ketting.",
  o = "Breng 5 Silver Bars naar Talvash del Kissel in Ironforge.",
  p = "Heb je de vijf zilverstaven waar ik om vroeg? Ik vertel je mijn droevige verhaal over de ketting die je nu hebt... maar pas als ik die staven heb! Help een gnoom alsjeblieft even, wil je?",
  c = "Wat mij betreft ben jij oké. Het kan me niet schelen wat de anderen over je zeggen... Grapje, grapje! Echt, bedankt, vriend.$B$BNou, de ketting die je hebt is een van mijn beste creaties. Maar er ontbreken drie edelstenen die helpen om magische kracht aan de ketting te binden. Ik heb hem een tijd geleden gemaakt voor een paladijn. Die had zichzelf een opdracht gegeven: hij wilde de \"kwaadaardige smet\" weghalen bij een opgraving in de Badlands die Uldaman heet.$B$BNou... die paladijn is in Uldaman gestorven, en dat was nog maar het begin van mijn ellende.",
  g = { {"juwelier", "jeweler"}, {"concurrent", "competitor"}, {"oneerlijke", "unfair (oneerlijk)"}, {"financiële ramp", "financial disaster"}, {"bevlekt", "stained, sullied (bevlekken)"}, {"zilverstaven", "silver bars (zilverstaaf)"}, {"bestelling", "order"}, {"eeuwigheid", "eternity"}, {"ketting", "necklace"}, {"edelstenen", "gems (edelsteen)"}, {"binden", "to bind"}, {"kwaadaardige smet", "evil taint"}, {"opgraving", "excavation, dig site"}, {"ellende", "misery, woes"} },
},

[17] = { en = "Uldaman Reagent Run", tier = 3,
  t = "Reagentia uit Uldaman",
  d = "Ik heb gehoord over een plant die pas is ontdekt: de Magenta Fungus Cap. Ze groeien in groepjes, diep in de opgraving van Uldaman. Misschien groeien ze ook ergens anders, maar voorlopig is dat de enige plek die ik ken. Ik wil onderzoeken of ze nuttig kunnen zijn in de alchemie, en daar kom jij in beeld.$B$BZoek de groepjes magenta hoedjes en breng me er twaalf. Let op: de groepjes kunnen giftige sporen uitspuwen als je ertegenaan stoot.$B$BAls je dit voor me doet, maak ik een portie van een van mijn beroemde herstellende elixers voor je!",
  o = "Breng 12 Magenta Fungus Caps naar Ghak Healtouch in Thelsamar.",
  p = "Heb je de magenta hoedjes die ik nodig heb voor mijn alchemistische werk? Geen hoedjes, geen beloning!",
  c = "Goed gedaan, $N, je hebt weer laten zien wat je waard bent! De hoedjes worden een interessant onderzoek, jazeker!$B$BEn nu, zoals beloofd: proef een van mijn sterkere herstellende drankjes uit mijn eigen voorraad...$B$BAls je een ervaren alchemist bent, kunnen we misschien nog meer zaken doen. Hoe dan ook, bedankt voor je hulp!",
  g = { {"reagentia", "reagents (reagens)"}, {"ontdekt", "discovered (ontdekken)"}, {"voorlopig", "for now"}, {"onderzoeken", "to study, to investigate"}, {"alchemie", "alchemy"}, {"daar kom jij in beeld", "that's where you come in"}, {"giftige sporen", "poisonous spores"}, {"uitspuwen", "to spew out"}, {"stoot", "bump, jostle (stoten)"}, {"portie", "batch, portion"}, {"herstellende", "restorative (herstellen)"}, {"voorraad", "stock, supply"}, {"ervaren", "skilled, experienced"}, {"zaken doen", "to do business"} },
},

[1192] = { en = "Indurium Ore", tier = 3,
  t = "Indurium-erts",
  p = "Ik wil indurium in verschillende onderdelen van onze racewagens verwerken, maar daarvoor heb ik grote hoeveelheden ruw indurium nodig.$B$BJe vindt indurium-erts in de opgraving van Uldaman in de Badlands, aan de overkant van de zee in Khaz Modan.$B$BDe gnomen halen hun eigen voorraad, dus het is belangrijk dat wij ook onze eigen voorraad krijgen. Zo kunnen we ze bijhouden.",
  c = "Uitstekend! Ik laat de ploeg meteen aan het werk gaan aan de onderdelen die we voor de volgende race nodig hebben.",
  g = { {"erts", "ore"}, {"onderdelen", "parts (onderdeel)"}, {"racewagens", "racers, racing vehicles (racewagen)"}, {"verwerken", "to integrate, to process"}, {"hoeveelheden", "amounts (hoeveelheid)"}, {"ruw", "raw"}, {"aan de overkant van", "across, on the other side of"}, {"bijhouden", "to keep pace with"}, {"ploeg", "crew"} },
},

[2200] = { en = "Back to Uldaman", tier = 3,
  t = "Terug naar Uldaman",
  d = "Een concurrent van mij heeft het gerucht verspreid dat mijn ketting de paladijn heeft vervloekt. Je begrijpt wel dat niemand vervloekte spullen wil kopen van een juwelier.$B$B$N, ik stel je een deal voor: vind de edelstenen en ik zet de ketting weer in elkaar. Dan moet jij wel overal vertellen dat ik GEEN vervloekte spullen maak!$B$BZoek in Uldaman naar aanwijzingen. Kijk misschien of het lichaam van de paladijn daar beneden ligt, want we weten dat hij de ketting als laatste had! Als je de edelstenen vindt, moet je dit gebruiken. Daarmee kun je contact met me opnemen hier in Ironforge.",
  o = "Zoek in Uldaman naar aanwijzingen over waar de ketting van Talvash nu is. De gedode paladijn over wie hij sprak, had de ketting als laatste.",
  c = "Remains of a Paladin: Als je het dagboek leest, blijkt dat de paladijn na veel moeite had ontdekt waar alle drie de ontbrekende edelstenen waren:$b$bDe Shadowforge-dwergen hebben de robijn verstopt in hun gebied achter barricades, terwijl ze met de troggs vochten om de macht over Uldaman.$b$bDe troggs hebben de topaas verstopt in een urn bij een paar ongewone bewoners van Uldaman: dwergen van de Alliance!$b$bEn ten slotte heeft de oudste van de troggs de saffier zelf genomen en gehouden.",
  g = { {"gerucht", "rumor"}, {"verspreid", "spread (verspreiden)"}, {"vervloekt", "cursed (vervloeken)"}, {"zet ... weer in elkaar", "reassemble (in elkaar zetten)"}, {"aanwijzingen", "clues (aanwijzing)"}, {"contact met me opnemen", "to contact me"}, {"gedode", "slain (doden)"}, {"dagboek", "journal, diary"}, {"blijkt", "turns out (blijken)"}, {"ontbrekende", "missing (ontbreken)"}, {"robijn", "ruby"}, {"topaas", "topaz"}, {"saffier", "sapphire"}, {"bewoners", "inhabitants (bewoner)"} },
},

[2318] = { en = "Translating the Journal", tier = 3,
  t = "Het dagboek vertalen",
  d = "Je zit min of meer vast. Je weet dat het boek vertaald moet worden in een taal die je begrijpt. Er zijn vast een heleboel mensen in de wereld die dat kunnen. Maar de dichtstbijzijnde plek waar misschien iemand is die het kan, is de buitenpost Kargath in de Badlands. Misschien is dat een goede plek om te beginnen.$b",
  o = "Zoek iemand die het dagboek van de paladijn kan vertalen. De dichtstbijzijnde plek waar misschien iemand is, is Kargath in de Badlands.",
  c = "Machtige $C, ik weet wat je hier in de Badlands doet. Ik weet dat je mijn talent voor talen zoekt. Je bent op zoek naar de onderdelen van die ketting die je in Uldaman hebt gevonden.$b$bVerbaasd? Dat hoeft niet. Het is mijn werk om zulke dingen te weten. Laten we liever bespreken wat jij gaat doen in ruil voor een vertaald dagboek. Geloof me: ik ben de enige die je zult vinden die het kan vertalen.$b$bNog beter: ik doe je een beter aanbod dan Dran Droffers. Dan kun je je deal met hen nog steeds afmaken. Nu wel geïnteresseerd, hè?",
  g = { {"min of meer", "more or less, of sorts"}, {"vast", "stuck; surely"}, {"vertaald", "translated (vertalen)"}, {"dichtstbijzijnde", "closest, nearest"}, {"buitenpost", "outpost"}, {"talent voor talen", "gift of tongues"}, {"verbaasd", "surprised"}, {"bespreken", "to discuss"}, {"in ruil voor", "in exchange for"}, {"aanbod", "offer"}, {"geïnteresseerd", "interested"} },
},

[3375] = { en = "Replacement Phial", tier = 3,
  t = "Een nieuw flesje",
  d = "Eh... heb je nog een waarzegflesje nodig? Dat meen je niet, toch? Wat heb je met het eerste gedaan?! We hebben hier nog veel werk voor de boeg, $r. Die flesjes groeien niet aan de bomen! Eigenlijk zou ik willen dat ze dat wel deden, want dan ging ik er een plukken. Ik heb er namelijk geen meer!!$B$BOm een nieuw flesje voor je te maken, heb ik het volgende nodig: een manadrankje, een stuk steenkool en wat zoete nectar. Vraag niet waarom. Breng me gewoon wat ik vraag, dan maak ik een nieuw flesje voor je.",
  o = "Breng een Mana Potion, Coal en Sweet Nectar naar Talvash del Kissel in Ironforge. Dan krijg je een nieuwe Talvash's Phial of Scrying.",
  p = "Om nog een flesje te maken heb ik een manadrankje, een stuk steenkool en wat zoete nectar nodig.$B$BDat, en blijkbaar een hele hoop geduld.",
  c = "De machtige avonturier levert. Hoera voor mij. Trouwens, ik heb gelogen: ik had nog een flesje. Pff, neem maar.$B$BNou, wat had je dan verwacht?! \"O, hier, neem er nog een! Ik ben gewoon een malloot die niets beters te doen heeft dan magische communicatiemiddelen uit te delen aan avonturiers!\" Maar wees gerust: wat je me hebt gegeven, is genoeg om nog een flesje voor je te maken als je dit ook kwijtraakt.$B$BBewijs alsjeblieft dat ik ongelijk heb en raak het nieuwe niet kwijt, oké?",
  g = { {"waarzegflesje", "phial of scrying"}, {"dat meen je niet", "you're kidding"}, {"veel werk voor de boeg", "a lot of work ahead"}, {"plukken", "to pick"}, {"steenkool", "coal"}, {"blijkbaar", "apparently"}, {"geduld", "patience"}, {"gelogen", "lied (liegen)"}, {"malloot", "goofball, fool"}, {"communicatiemiddelen", "communication devices (communicatiemiddel)"}, {"wees gerust", "rest assured"}, {"kwijtraakt", "lose (kwijtraken)"}, {"ongelijk", "wrong (ongelijk hebben)"} },
},

[7070] = { en = "Shadowshard Fragments", tier = 3,
  t = "Shadowshard-scherven",
  d = "Ik ben kort geleden begonnen met het testen van verschillende kristallen en hun arcane eigenschappen. Lady Proudmoore heeft me toestemming gegeven om reizigers die naar Desolace gaan te vragen een plek te zoeken die Maraudon heet. In de verwoeste tempel zijn grote elementalen die bestaan uit paarsachtige stenen. Ik heb die stenen shadowshards genoemd.$B$BAls je besluit die kant op te gaan en een paar van de kristallen vindt, zou ik je heel dankbaar zijn. Ik kan er zelfs een klein sieraad voor je van maken, als je dat zou willen.",
  o = "Verzamel 10 Shadowshard Fragments in Maraudon en breng ze naar Archmage Tervosh in Theramore, aan de kust van Dustwallow Marsh.",
  p = "Ben je al op reis geweest? Ik weet dat het behoorlijk gevaarlijk is, maar als het je lukt, is het zeker de moeite waard.",
  c = "Deze zijn perfect, $N. Er zijn ook andere avonturiers van daar teruggekomen, en met wat zij brachten kon ik deze maken... Neem er gerust een voor je harde werk. En nogmaals bedankt voor meer monsters om te onderzoeken.",
  g = { {"scherven", "shards, fragments (scherf)"}, {"kristallen", "crystals (kristal)"}, {"arcane", "arcane (arcaan)"}, {"eigenschappen", "properties (eigenschap)"}, {"toestemming", "permission, leave"}, {"verwoeste", "ruined (verwoesten)"}, {"elementalen", "elementals (elementaal)"}, {"paarsachtige", "purplish (paarsachtig)"}, {"sieraad", "piece of jewelry, trinket"}, {"de moeite waard", "worth it"}, {"gerust", "feel free, by all means"}, {"monsters", "samples (monster)"} },
},

[1360] = { en = "Reclaimed Treasures", tier = 3,
  t = "Teruggehaalde schatten",
  d = "Ik had een mooie baan als graver bij de opgraving van Uldaman in de Badlands... tot die vervloekte troggs kwamen. Ik ontsnapte ternauwernood met een heel vel, en verder niets. In de chaos liet ik mijn kostbaarste bezit achter. Het ligt in mijn kist, veilig voor de troggs, dat wel. Maar het staat midden tussen ze in.$B$BAls je het voor me kunt halen, sta ik bij je in het krijt, met mijn eer en met mijn geld! Een kist met mijn naam erop staat aan het eind van de North Common Hall. Dat is de kist die je open moet krijgen.",
  o = "Haal het kostbare bezit van Krom Stoutarm uit zijn kist in de North Common Hall van Uldaman en breng het naar hem in Ironforge.",
  p = "Nou, is het je gelukt om die troggs lang genoeg een pak slaag te geven om in mijn kist te komen en mijn schat te pakken?",
  c = "Ah, ik voel me weer compleet. Hartelijk bedankt.$B$BSommige dwergen zijn gek op de glans van metaal, en sommige op de schittering van edelstenen... maar een Stoutarm zonder zijn geliefde bierpul in de hand is eigenlijk geen echte Stoutarm!",
  g = { {"graver", "digger"}, {"ternauwernood", "barely"}, {"met een heel vel", "with one's hide intact"}, {"kostbaarste", "most treasured (kostbaar)"}, {"bezit", "possession"}, {"kist", "chest"}, {"midden tussen ze in", "right in the thick of them"}, {"bij je in het krijt staan", "to be in your debt"}, {"eer", "honor"}, {"een pak slaag", "a beating"}, {"glans", "luster, shine"}, {"schittering", "glint, sparkle"}, {"bierpul", "beer stein"} },
},

[2201] = { en = "Find the Gems", tier = 3,
  t = "Vind de edelstenen",
  d = "Het dagboek van de paladijn geeft misschien de enige aanwijzingen die Uldaman zal geven over waar de edelstenen van de ketting zijn. Als wat de paladijn schreef nog klopt, moet je afrekenen met de Shadowforge-dwergen en de troggs, die vechten om de macht over de opgraving.$B$BMet deze kennis begint de zoektocht naar de edelstenen echt. Als alle edelstenen gevonden zijn, moet je het Talvash in Ironforge laten weten via de Phial of Scrying, zoals hij heeft gevraagd.",
  o = "Vind de robijn, de saffier en de topaas die verspreid liggen in Uldaman. Neem daarna op afstand contact op met Talvash del Kissel. Gebruik daarvoor de Phial of Scrying die hij je eerder heeft gegeven.$B$BUit het dagboek weet je...$B* De robijn is verstopt in een Shadowforge-gebied achter barricades.$B* De topaas is verstopt in een urn in een van de gebieden van de troggs, bij een paar dwergen van de Alliance.$B* De saffier is ingenomen door Grimlok, de leider van de troggs.",
  p = "Het beeld van Talvash wordt scherp in het water van de waarzegkom.$b$b\"Wauw, je leeft nog! Heb je de edelstenen gevonden? Ben jij echt de redder van mijn reputatie waar ik op hoopte? Zeg alsjeblieft dat je geen lading van het flesje hebt verspild om alleen maar te kletsen. Die dingen zijn NIET goedkoop, en ik zit al in grote geldnood.\"",
  c = "Jep, dat zijn inderdaad de drie edelstenen. Goed gedaan! Helaas is je werk nog niet helemaal klaar.$B$BNee, ik probeer je niet te bedriegen, gekke $C. Het gaat om het maken van magische sieraden: sieraden van Talvash del Kissel-kwaliteit! Je hebt een sterke krachtbron nodig om ze wat pit te geven. Nou, die ketting heeft geen pit meer over.",
  g = { {"klopt", "is correct (kloppen)"}, {"afrekenen met", "to deal with"}, {"zoektocht", "search"}, {"verspreid", "scattered (verspreiden)"}, {"op afstand", "remotely"}, {"ingenomen", "claimed, taken (innemen)"}, {"wordt scherp", "comes into focus"}, {"waarzegkom", "scrying bowl"}, {"redder", "savior"}, {"lading", "charge"}, {"verspild", "wasted (verspillen)"}, {"kletsen", "to chat"}, {"geldnood", "financial straits"}, {"bedriegen", "to cheat, to trick"}, {"krachtbron", "power source"}, {"pit", "oomph, spirit"} },
},

[2204] = { en = "Restoring the Necklace", tier = 3,
  t = "De ketting herstellen",
  d = "Je moet wat \"pit\" voor de ketting vinden, en Uldaman is daar eigenlijk waarschijnlijk de beste plek voor. Ik denk dat daar een heleboel constructen rondlopen, toch? Nou, schakel het grootste, gemeenste construct daar uit en pak zijn krachtbron! Ik ben er vrij zeker van dat ik die krachtbron in de ketting kan smelten.$B$BZonder die krachtbron is het onmogelijk om de ketting te repareren. Kom terug naar mij in Ironforge als je hem hebt, dan maken we alles voor je in orde!",
  o = "Haal een krachtbron bij het machtigste construct dat je in Uldaman kunt vinden en breng hem naar Talvash del Kissel in Ironforge.",
  p = "Je bent niet eens gestopt om jezelf wat op te frissen na Uldaman, hè? Je bent meteen hierheen gekomen, en de kerkergeur die nog om je heen hangt, kan je niets schelen. Nou, laten we hopen dat dit bezoek alleen stinkt, en niet ook nog nutteloos is.$B$BHeb je de krachtbron voor de ketting?",
  c = "Nou ja zeg, ik ben echt blij dat jij en deze krachtbron heel zijn. Het duurt even voordat ik de krachtbron met magie aan de ketting heb vastgesmolten, nu de edelstenen er weer in zitten. Maar als het klaar is, is de ketting van jou!$B$BJe bent enthousiast, hè? Helemaal tintelend van verwachting? Waar heb ik die spreukfocus nou gelaten...",
  g = { {"herstellen", "to restore"}, {"constructen", "constructs (construct)"}, {"schakel ... uit", "take out (uitschakelen)"}, {"gemeenste", "baddest, meanest (gemeen)"}, {"smelten", "to fuse, to melt"}, {"in orde", "all fixed up"}, {"op te frissen", "to tidy up (opfrissen)"}, {"kerkergeur", "dungeon odor"}, {"kan je niets schelen", "you don't care at all"}, {"nutteloos", "useless"}, {"heel", "in one piece, whole"}, {"vastgesmolten", "fused (vastsmelten)"}, {"tintelend", "tingly (tintelen)"}, {"verwachting", "anticipation"}, {"spreukfocus", "spell focus"} },
},

[2361] = { en = "Restoring the Necklace", tier = 3,
  t = "De ketting herstellen",
  c = "Ik geef je deze ketting met plezier, machtige $C. Je hebt me een onbetaalbare dienst bewezen, en daarvoor dank ik je. Draag hem met trots, en zorg dat je luid en vaak zegt wie hem voor je heeft gemaakt!$B$BEn als je er ook bij kunt zeggen dat hij echt niet vervloekt is, zou dat geweldig zijn.",
  g = { {"met plezier", "gladly"}, {"onbetaalbare", "invaluable, priceless (onbetaalbaar)"}, {"een dienst bewezen", "did a service (een dienst bewijzen)"}, {"met trots", "with pride"}, {"luid", "loudly"}, {"vervloekt", "cursed"} },
},

[1139] = { en = "The Lost Tablets of Will", tier = 3,
  t = "De verloren tabletten van de wil",
  d = "We hebben de Shadowforge-clan vertraagd door hun weg naar Blackrock Spire af te snijden, maar de opdracht van Hammertoe is nog niet volbracht. Zijn dood mag niet voor niets zijn geweest. Hij droomde ervan de Tablet of Will te vinden: een stuk steen waarin de titanen zelf magie hebben gegraveerd. Daarmee gaven ze hun creaties leven, zodat ze een eigen wil kregen. Dat zeggen de legendes tenminste.$B$BWe moeten de tablet nog steeds vinden voordat de Shadowforge-clan hem vindt.$B$BGa terug naar Uldaman, vind de tablet en kom meteen hier terug.",
  o = "Vind de Tablet of Will en breng hem terug naar Advisor Belgrum in Ironforge.",
  p = "De opdracht van Hammertoe moet worden volbracht, $N. Dat ben ik hem op zijn minst verschuldigd.$B$BJe terugkeer naar Uldaman is heel belangrijk. Niet alleen voor dat doel, maar ook voor de veiligheid van alle dwergen. Wie weet hoe machtig het leger golems van de Dark Irons zou worden als zij de tablet in handen hebben.",
  c = "<Advisor Belgrum schudt ongelovig zijn hoofd als je hem het stuk steen geeft.>$B$B$N, dit is ongelooflijk. Ik laat dit zo snel mogelijk naar de magiërs van de koning brengen. Zij willen het onderzoeken om te ontdekken of de legendes waar zijn. Maar daar praten we een andere keer over. Je hebt ons volk meer geholpen dan ik ooit had verwacht. Dank je wel.",
  g = { {"vertraagd", "slowed (vertragen)"}, {"af te snijden", "to cut off (afsnijden)"}, {"volbracht", "fulfilled (volbrengen)"}, {"voor niets", "in vain"}, {"gegraveerd", "inscribed (graveren)"}, {"creaties", "creations (creatie)"}, {"legendes", "legends (legende)"}, {"verschuldigd", "owed, indebted"}, {"terugkeer", "return"}, {"veiligheid", "safety"}, {"in handen hebben", "to have in one's hands"}, {"ongelovig", "in disbelief"}, {"magiërs", "mages (magiër)"} },
},

[2864] = { en = "Tran'rek", tier = 3,
  t = "Tran'rek",
  d = "Mijn neef Tran'rek zit in de problemen. Hij heeft me weken geleden een lading scarabeeschilden beloofd, en hij heeft ze nog steeds niet geleverd. Hij is mijn neef, dus ik zou het jammer vinden als ik iemand naar Gadgetzan moet sturen om iets bij hem te breken.$B$BKun jij met Tran'rek gaan praten? Zeg hem dat hij die levering moet regelen voordat ik iets overhaasts doe.$B$BGadgetzan ligt in het noorden van Tanaris, in Kalimdor.",
  o = "Praat met Tran'rek in Gadgetzan.",
  c = "Hallo!$B$BO, heb je mijn neef Krazek gesproken? Hoe gaat het met hem? Ik hoop dat het goed met hem gaat in Booty Bay...$B$BScarabeeschilden, zeg je? Nou... laat me je een verhaal vertellen...",
  g = { {"neef", "cousin"}, {"zit in de problemen", "is in a tight spot"}, {"lading", "load"}, {"scarabeeschilden", "scarab shells (scarabeeschild)"}, {"geleverd", "delivered (leveren)"}, {"levering", "delivery"}, {"regelen", "to arrange, to sort out"}, {"overhaasts", "rash, hasty"} },
},

[2865] = { en = "Scarab Shells", tier = 3,
  t = "Scarabeeschilden",
  d = "De scarabeeën van Tanaris hebben heel harde schilden! Hard genoeg om ze als bouwmateriaal voor allerlei dingen te gebruiken. Zo veel dingen!$B$BSterker nog, die schilden zijn zo nuttig... dat er op de scarabeeën is gejaagd tot ze bijna uitgestorven waren!$B$BIk weet waar er nog meer scarabeeën zijn. Als je belooft dat je me hun schilden brengt, vertel ik je waar ze zijn. Beloofd?$B$BOké, de scarabeeën hebben een kolonie in Zul'Farrak. Ik denk dat de trollen niet op ze jagen voor hun schilden.$B$BMaar jij wel! Ga naar Zul'Farrak en haal schilden zonder barsten voor me!",
  o = "Breng 5 Uncracked Scarab Shells naar Tran'rek in Gadgetzan.",
  p = "Heb je de schilden? Mijn neef in Booty Bay wacht op een lading, en hij wordt ongeduldig!",
  c = "O, geweldig! Je hebt ze!$B$BBedankt, $N. Je bent echt mijn redder!",
  g = { {"scarabeeën", "scarabs (scarabee)"}, {"schilden", "shells (schild)"}, {"bouwmateriaal", "building material"}, {"sterker nog", "in fact, even more"}, {"gejaagd", "hunted (jagen)"}, {"uitgestorven", "extinct (uitsterven)"}, {"kolonie", "colony"}, {"barsten", "cracks (barst)"}, {"ongeduldig", "impatient"}, {"redder", "lifesaver, savior"} },
},

[3042] = { en = "Troll Temper", tier = 3,
  t = "Hardingsmiddel van de trollen",
